  ($t$Seigneur momie$t$, $t$Mummy Lord$t$, $t$Petite$t$, $t$Mort-vivant$t$, $t$loyal mauvais$t$, 17, $t$armure naturelle$t$, 187, $t$25d8 + 75$t$, $t${"walk":30}$t$::jsonb, $t${"str":18,"dex":10,"con":17,"int":11,"wis":19,"cha":16}$t$::jsonb, $t${"int":5,"wis":9}$t$::jsonb, $t${"Histoire":5,"Perception":9,"Religion":5}$t$::jsonb, null, null, $t$nécrotique, poison$t$, $t$charmé, épuisement, effrayé, paralysé, empoisonné$t$, $t$vision véritable 18 m, Perception passive 19$t$, $t$commun et trois autres langues$t$, 15, 13000, 5, 10, $t$[{"name":"Résistance légendaire (3/jour, ou 4/jour dans son antre)","description":"Si la momie rate un jet de sauvegarde, elle peut choisir de le réussir à la place."},{"name":"Résistance à la magie","description":"La momie a l'avantage aux jets de sauvegarde contre les sorts et autres effets magiques."},{"name":"Restauration morte-vivante","description":"Si elle est détruite, la momie obtient un nouveau corps en 24 heures si son cœur est intact, revenant à la vie avec tous ses points de vie. Le nouveau corps apparaît dans un espace inoccupé de son antre. Le cœur est un objet de taille TP (CA 17, 10 PV, immunité à tous les dégâts sauf de feu)."}]$t$::jsonb, $t$[{"name":"Attaques multiples","description":"La momie effectue une attaque de Poing putride ou de Canalisation d'énergie négative, et utilise Regard terrifiant."},{"name":"Poing putride","description":"Jet d'attaque au corps à corps : +9, allonge 1,50 m. 15 (2d10 + 4) dégâts contondants plus 10 (3d6) dégâts nécrotiques. Si la cible est une créature, elle est maudite : elle ne peut pas récupérer de points de vie, ne tire aucun bénéfice des repos longs, et son maximum de points de vie diminue de 10 (3d6) toutes les 24 heures. Une créature réduite à 0 point de vie par cette attaque meurt et tombe en poussière."},{"name":"Canalisation d'énergie négative","description":"Jet d'attaque à distance : +9, portée 18 m. 25 (6d6 + 4) dégâts nécrotiques."},{"name":"Regard terrifiant","description":"Jet de sauvegarde de Sagesse : DD 17, une créature que la momie voit à 18 m ou moins. Échec : 25 (6d6 + 4) dégâts psychiques, et la cible subit l'état paralysé jusqu'à la fin du prochain tour de la momie."},{"name":"Incantation","description":"La momie lance l'un des sorts suivants, sans composantes matérielles et en utilisant la Sagesse comme caractéristique d'incantation (DD de sauvegarde des sorts 17, +9 au toucher avec les attaques de sort). À volonté : Dissipation de la magie, Thaumaturgie. 1/jour chacun : Animation des morts, Mise à mal, Fléau d'insectes."}]$t$::jsonb, $t$[]$t$::jsonb, $t$[{"name":"Tourbillon de sable","description":"Déclencheur : la momie est touchée par un jet d'attaque. Réaction : elle ajoute 2 à sa CA contre l'attaque, ce qui peut la faire rater, et se téléporte jusqu'à 18 m dans un espace inoccupé qu'elle voit. Chaque créature de son choix qu'elle voit à 1,50 m ou moins de son point d'arrivée subit l'état aveuglé jusqu'à la fin du prochain tour de la momie."}]$t$::jsonb, $t$[{"name":"Regard","description":"La momie utilise Regard terrifiant. Elle ne peut pas reprendre cette action avant le début de son prochain tour."},{"name":"Frappe nécrotique","description":"La momie effectue une attaque de Poing putride ou de Canalisation d'énergie négative."},{"name":"Injonction terrible","description":"La momie lance Injonction (version de niveau 2), avec la même caractéristique d'incantation qu'Incantation. Elle ne peut pas reprendre cette action avant le début de son prochain tour."}]$t$::jsonb),
  ($t$Nalfeshnee$t$, $t$Nalfeshnee$t$, $t$Grande$t$, $t$Fiélon$t$, $t$chaotique mauvais$t$, 18, $t$armure naturelle$t$, 184, $t$16d10 + 96$t$, $t${"walk":20,"fly":30}$t$::jsonb, $t${"str":21,"dex":10,"con":22,"int":19,"wis":12,"cha":15}$t$::jsonb, $t${"con":11,"int":9,"wis":6,"cha":7}$t$::jsonb, $t${}$t$::jsonb, null, $t$froid, feu, foudre$t$, $t$poison$t$, $t$effrayé, empoisonné$t$, $t$vision véritable 36 m, Perception passive 11$t$, $t$abyssal; télépathie 36 m$t$, 13, 10000, 5, 5, $t$[{"name":"Restauration démoniaque","description":"Si le nalfeshnee meurt hors des Abysses, son corps se dissout en ichor et il obtient instantanément un nouveau corps, revenant à la vie avec tous ses points de vie quelque part dans les Abysses."},{"name":"Résistance à la magie","description":"Le nalfeshnee a l'avantage aux jets de sauvegarde contre les sorts et autres effets magiques."}]$t$::jsonb, $t$[{"name":"Attaques multiples","description":"Le nalfeshnee effectue trois attaques de Déchirure."},{"name":"Déchirure","description":"Jet d'attaque au corps à corps : +10, allonge 3 m. 16 (2d10 + 5) dégâts tranchants plus 11 (2d10) dégâts de force."},{"name":"Téléportation","description":"Le nalfeshnee se téléporte jusqu'à 36 m dans un espace inoccupé qu'il voit."}]$t$::jsonb, $t$[{"name":"Nimbe d'horreur (recharge 5-6)","description":"Jet de sauvegarde de Sagesse : DD 15, chaque créature dans une Émanation de 4,50 m autour du nalfeshnee. Échec : 28 (8d6) dégâts psychiques, et la cible subit l'état effrayé pendant 1 minute, jusqu'à ce qu'elle subisse des dégâts ou qu'elle termine son tour hors de vue du nalfeshnee. Réussite : la cible est immunisée contre le Nimbe d'horreur de ce nalfeshnee pendant 24 heures."}]$t$::jsonb, $t$[{"name":"Poursuite","description":"Déclencheur : une autre créature que le nalfeshnee voit termine son déplacement à 36 m ou moins de lui. Réaction : le nalfeshnee utilise Téléportation, mais son point d'arrivée doit se trouver à 3 m ou moins de la créature déclencheuse."}]$t$::jsonb, $t$[]$t$::jsonb),
  ($t$Guenaude nocturne$t$, $t$Night Hag$t$, $t$Moyenne$t$, $t$Fiélon$t$, $t$neutre mauvais$t$, 17, $t$armure naturelle$t$, 112, $t$15d8 + 45$t$, $t${"walk":30}$t$::jsonb, $t${"str":18,"dex":15,"con":16,"int":16,"wis":14,"cha":16}$t$::jsonb, $t${}$t$::jsonb, $t${"Tromperie":6,"Perspicacité":5,"Perception":5,"Discrétion":5}$t$::jsonb, null, $t$froid, feu$t$, null, null, $t$vision dans le noir 36 m, Perception passive 15$t$, $t$abyssal, commun, infernal, primordial$t$, 5, 1800, 3, 5, $t$[{"name":"Résistance à la magie","description":"La guenaude a l'avantage aux jets de sauvegarde contre les sorts et autres effets magiques."},{"name":"Sac à âmes","description":"La guenaude possède un sac à âmes ; tant qu'elle le tient ou le porte, elle peut utiliser l'action Hantise cauchemardesque. Le sac a CA 15, 20 PV et la résistance à tous les dégâts. Il tombe en poussière s'il est réduit à 0 point de vie, libérant les âmes qu'il contient. La guenaude peut créer un nouveau sac au bout de 7 jours."}]$t$::jsonb, $t$[{"name":"Attaques multiples","description":"La guenaude effectue deux attaques de Griffe."},{"name":"Griffe","description":"Jet d'attaque au corps à corps : +7, allonge 1,50 m. 13 (2d8 + 4) dégâts tranchants."},{"name":"Incantation","description":"La guenaude lance l'un des sorts suivants, sans composantes matérielles et en utilisant l'Intelligence comme caractéristique d'incantation (DD de sauvegarde des sorts 14). À volonté : Détection de la magie, Forme éthérée, Projectile magique. 2/jour chacun : Assassin imaginaire, Changement de plan."},{"name":"Hantise cauchemardesque (1/jour)","description":"Depuis le plan éthéré, la guenaude lance Songe, avec la même caractéristique d'incantation qu'Incantation. Elle seule peut être la messagère du sort, et la cible doit être une créature qu'elle voit sur le plan matériel. Le sort échoue et est perdu si la cible est sous l'effet de Protection contre le mal et le bien ou dans un Cercle magique. Si la cible subit des dégâts du sort, son maximum de points de vie diminue d'autant. Si le sort la tue, son âme est piégée dans le sac à âmes de la guenaude, et elle ne peut pas être ramenée à la vie tant que son âme n'est pas libérée."}]$t$::jsonb, $t$[{"name":"Métamorphose","description":"La guenaude prend la forme d'un humanoïde de taille P ou M, ou reprend sa forme véritable. À part sa taille, ses statistiques sont les mêmes sous chaque forme. L'équipement qu'elle porte ou transporte n'est pas transformé."}]$t$::jsonb, $t$[]$t$::jsonb, $t$[]$t$::jsonb),
